	it("reads plain, quoted, continued, and block values, and skips nested maps", () => {
		const fields = parseFrontmatter(
			[
				"---",
				"name: release",
				"description: Cut a release: tag,",
				"  then publish",
				'quoted: "a \\"b\\""',
				"single: 'it''s'",
				"comment: yes # really",
				"folded: >",
				"  one",
				"  two",
				"",
				"  three",
				"literal: |-",
				"  one",
				"    two",
				"metadata:",
				"  author: me",
				"---",
				"body",
			].join("\n"),
		);
		expect(Object.fromEntries(fields ?? [])).toStrictEqual({
			name: "release",
			description: "Cut a release: tag, then publish",
			quoted: 'a "b"',
			single: "it's",
			comment: "yes",
=====
	});

	it("is undefined when no skill is listed", () => {
		const dir = tempDir();
		expect(formatSkillsSection(new Map(), "the read tool")).toBeUndefined();
		expect(
			formatSkillsSection(
				new Map([["release", skill(dir, { disableModelInvocation: true })]]),
				"the read tool",
			),
		).toBeUndefined();
	});
});

describe("skillsSection", () => {
	const render = (
		tools: string[],
		skills = new Map([["release", skill(tempDir())]]),
	) =>
		skillsSection(skills).render(
			{
				agent: { tools: tools.map((name) => ({ name })) },
			} as unknown as PromptInput,
			BACKGROUND_CONTEXT,
		);

	it("names the read tool, or workspace.read when pit's typescript tool is the way to read", async () => {
		expect(await render(["read", "bash", "typescript"])).toContain(
			"Use the read tool to load",
		);
		expect(await render(["typescript"])).toContain(
			"Use workspace.read to load",
		);
		expect(await render(["bash"])).toContain("Use the read tool to load");
	});

	it("renders the same text every time", async () => {
		const skills = new Map([["release", skill(tempDir())]]);
		const section = skillsSection(skills);
		const input = { agent: { tools: [] } } as unknown as PromptInput;
		const first = await section.render(input, BACKGROUND_CONTEXT);
		skills.clear();
		expect(await section.render(input, BACKGROUND_CONTEXT)).toBe(first);
		expect(section.key).toBe("available_skills");
	});
});

